import urllib.request
dna = open("/app/gblock.txt").read().strip()
alt = {
 'A':['GCA','GCT','GCC','GCG'],'R':['CGT','CGC','CGA','CGG','AGA','AGG'],'N':['AAT','AAC'],'D':['GAT','GAC'],
 'C':['TGT','TGC'],'Q':['CAA','CAG'],'E':['GAA','GAG'],'G':['GGA','GGG','GGT','GGC'],'H':['CAT','CAC'],
 'I':['ATT','ATC','ATA'],'L':['CTG','CTC','CTA','CTT','TTA','TTG'],'K':['AAA','AAG'],'M':['ATG'],'F':['TTT','TTC'],
 'P':['CCT','CCC','CCA','CCG'],'S':['AGC','AGT','TCT','TCC','TCA','TCG'],'T':['ACT','ACC','ACA','ACG'],
 'V':['GTG','GTC','GTA','GTT'],'W':['TGG'],'Y':['TAT','TAC']
}
tbl = {}
for aa,cs in alt.items():
    for c in cs: tbl[c]=aa
prot = "".join(tbl[dna[i:i+3]] for i in range(0,len(dna),3))
import re
locs = [m.start() for m in re.finditer(r'GGSGGSGGS', prot)]
segs = [prot[:locs[0]], prot[locs[0]+9:locs[1]], prot[locs[1]+9:locs[2]], prot[locs[2]+9:locs[3]], prot[locs[3]+9:]]
def getblock(pid, key):
    u = urllib.request.urlopen("https://www.rcsb.org/fasta/entry/"+pid, timeout=20)
    t = u.read().decode()
    for b in t.split(">")[1:]:
        if key in b.split("|")[0]:
            return "".join(l for l in b.splitlines()[1:] if l)
refs = [getblock("1AK4","1AK4_2"), None, None, getblock("2H5Q","2H5Q_1"), getblock("3KZY","3KZY_1")]
for i in (0,3,4):
    a = segs[i]
    b = refs[i]
    if b[0]=="M": b=b[1:]
    print("=== seg",i, "lens", len(a), len(b))
    for j in range(min(len(a),len(b))):
        if a[j]!=b[j]:
            print("first diff at", j, a[j], b[j])
            print("a", a[max(0,j-10):j+10])
            print("b", b[max(0,j-10):j+10])
            break
    else:
        print("common part same, tail of b:", b[len(a):])
